#!/usr/bin/env bash
# L-SI box 84 milestone 2 (ii) self-check: pins; CYC instances regenerated byte-equal; meas83 and priv84 re-run and diffed. The climbs
# (climb84.py, seeds 11-14, 1500 iterations) are not re-run (minutes); their best genomes are pinned and re-measured.
set -euo pipefail
cd "$(dirname "$0")"
sha1sum -c --quiet --strict pins.sha1
t=$(mktemp -d); mkdir -p "$t/inst"; bash mkinst_m2.sh "$t/inst"
for i in CY2_lr CY2_hp CY3_hp CY4_hp; do
  cmp -s "$t/inst/$i.json" inst/$i.json
  python3 -I -B ../../box83/meas83.py inst/$i.json ../../box81 -v > "$t/m"; diff -q "$t/m" out/meas_$i.out
done
python3 -I -B priv84.py ../../box81 inst/CY2_lr.json inst/CY2_hp.json inst/CY3_hp.json inst/CY4_hp.json ../../box83/inst/LR3_exitup.json ../inst/HP3_mup.json ../inst/HP4_mup.json ../inst/HP5_mup.json > "$t/p"; diff -q "$t/p" out/priv84.out
python3 -I -B priv84.py ../../box81 inst/climb_s1*.json > "$t/p"; diff -q "$t/p" out/priv84_climbs.out
rm -rf "$t"
echo "box 84 m2 checks: PASS"
